window.LESSONS = {"1.1":[{"id":"1.1-1","title":"Build the team from the services","preview":"Start with the work. Then choose the people.","explain":["A project needs capabilities, not just job titles. List the services required by the building, site, delivery method, and agreement.","Separate your firm’s work from consultant work and owner-provided work. Assign every interface. A missing service creates a gap. Two uncoordinated scopes can create duplicate work."],"steps":["Example: a restaurant renovation needs architecture, structure, MEP, kitchen planning, and a site survey.","Read the agreements to identify who obtains each service.","Ask the kitchen specialist for equipment sizes and loads. Ask MEP to design the connections.","Record who issues each input, who uses it, and when it is due."],"question":"Does hiring a kitchen consultant automatically include electrical connection design?","answer":"No. Check the selected scope. Assign the equipment information and connection design separately.","trap":"Never assume “consultant coordination” means every specialist service is included.","refs":["R06","R12","R31"],"visual":null,"table":{"headers":["Service","Produces","Needs"],"rows":[["Kitchen","Equipment list + loads","Owner menu and equipment choices"],["MEP","Power, water, exhaust design","Equipment data"],["Architecture","Space + clearances","Equipment and engineering layouts"]]}},{"id":"1.1-2","title":"Compare consultants fairly","preview":"A low fee is useful only when the scope fits.","explain":["Compare candidates against the same service description. Then review experience, licensure, capacity, availability, insurance, and coordination.","Separate a requirement from a preference. A legally required qualification is a gate. It cannot be offset by a cheap fee or a high score elsewhere."],"steps":["Example: a museum needs a specialist ready for a four-week design period.","Firm A charges $12,000 but cannot start for six weeks.","Firm B charges $14,000 and has an available qualified team.","First resolve feasibility and scope. Then compare the prices of viable options."],"question":"Should you average a failed licensing requirement into a weighted score?","answer":"No. Eliminate or resolve the failure first. Score only qualified options.","trap":"A firm’s reputation does not confirm that its proposed staff are available.","refs":["R06","R35"],"visual":null,"table":{"headers":["Check","Evidence"],"rows":[["Relevant skill","Comparable projects and actual staff resumes"],["Availability","Written staffing and milestone commitment"],["Scope match","Deliverable and exclusion comparison"],["Risk","Insurance, conflicts, and licensing checks"]]}},{"id":"1.1-3","title":"Read a responsibility matrix","preview":"One row answers: who prepares, checks, and decides?","explain":["A responsibility matrix assigns people to outputs. A RACI matrix is one common format: responsible, accountable, consulted, informed.","Define the labels before using them. Internal accountability does not replace contractual authority. An owner approval may still be required."],"steps":["Example: an equipment layout must be issued Friday.","The architect prepares the plan. The kitchen consultant supplies equipment inputs.","The PM checks coordination. The owner approves operational choices.","Name people and dates. “The team” is too vague to manage a late decision."],"question":"Can the PM approve a scope increase just because the matrix says “accountable”?","answer":"Only if the contract or a valid delegation grants that authority. The matrix alone does not.","trap":"Assigning a checker does not remove the author’s responsibility for their work.","refs":["R06","R33"],"visual":null,"table":{"headers":["Output","Prepare","Review / input","Decision"],"rows":[["Equipment plan","Architect","Kitchen + MEP","Owner operations approval"],["Coordination issue","Discipline author","PM + affected trades","Authorized design lead"],["Extra-service proposal","PM","Principal","Owner authorization"]]}},{"id":"1.1-4","title":"Plan the handoffs","preview":"The gap between two scopes is a common failure point.","explain":["An interface is the place where one person’s output becomes another person’s input. Track both sides.","A kickoff should establish delivery dates, file rules, decision routes, and review time. It should also expose assumptions before they become rework."],"steps":["Example: the civil engineer provides finished floor elevations.","Structure needs them for foundations. Architecture needs them for accessible entries.","Set a shared reference datum and an issue date.","If the elevation changes, notify both users. Recheck foundations, slopes, and thresholds."],"question":"What is missing from “civil sends the model Friday”?","answer":"The required content, reference system, responsible recipient, review time, and acceptance criteria.","trap":"Receiving a file is not the same as receiving a usable, coordinated input.","refs":["R28","R30","R33"],"visual":null,"table":null}],"1.2":[{"id":"1.2-1","title":"Separate salary, cost, and billing","preview":"Three hourly rates answer three different questions.","explain":["Salary rate is direct pay. A burdened rate includes the costs specified in the problem. A billing rate is what is charged to the client.","Always write the rate’s basis next to its units. Do not multiply by overhead twice. Do not subtract salary costs from a fee and call the result profit."],"steps":["Example: a person works 10 hours. Salary is $40/hour. Billing is $120/hour.","Direct salary cost = 10 × $40 = $400.","Potential hourly billing = 10 × $120 = $1,200, if the agreement permits that billing.","The $800 difference must also cover applicable overhead and profit."],"question":"A problem already gives a $90/hour burdened cost. Should you automatically add overhead again?","answer":"No. First check what the burdened rate includes.","trap":"Rate names vary. Use the definitions supplied in the question.","refs":["R04","R05"],"visual":null,"table":{"headers":["Basis","10-hour example","Use"],"rows":[["Direct salary: $40/h","$400","Direct labor budget"],["Burdened cost: $90/h","$900","Cost forecast on this stated basis"],["Billing: $120/h","$1,200","Hourly fee calculation"]]}},{"id":"1.2-2","title":"Turn a fee into available hours","preview":"Subtract outside costs before budgeting internal labor.","explain":["A gross fee can include money owed to consultants and other direct expenses. That money is not all available for your staff.","A target net multiplier relates net service revenue to direct salary cost. It is a planning assumption, not a guaranteed profit."],"steps":["Example: gross fee $150,000; consultants $45,000; other direct expenses $5,000.","Net service revenue = $150,000 − $45,000 − $5,000 = $100,000.","At a target multiplier of 2.5, direct salary budget = $100,000 ÷ 2.5 = $40,000.","At an average $50 salary/hour, plan 800 hours. Assign those hours to tasks, including review."],"question":"Can you calculate staff hours directly from the full $150,000?","answer":"Not with this method. First remove the stated direct expenses and apply the multiplier.","trap":"Do not use a billing rate where the formula calls for direct salary.","refs":["R04","R05"],"visual":"fee","table":null},{"id":"1.2-3","title":"Check actual staff capacity","preview":"A 40-hour week is not 40 available project hours.","explain":["Capacity is the time people can actually devote to this project. Deduct other commitments and non-project time once.","Compare demand and capacity by week and by skill. A surplus of junior drafting hours cannot replace a required senior review."],"steps":["Example: a three-week task needs 100 designer hours.","The designer has 24 available project hours each week. Total capacity = 3 × 24 = 72 hours.","The shortage is 100 − 72 = 28 hours.","Add qualified capacity, change the sequence, or seek an authorized date change."],"question":"Two projects each need 24 hours from the same person next week. Their project capacity is 32 hours. What is the overload?","answer":"48 − 32 = 16 hours. Resolve the conflict before promising both deadlines.","trap":"Do not add staffing without allowing for onboarding and coordination.","refs":["R06"],"visual":"capacity","table":null},{"id":"1.2-4","title":"Forecast the work still to finish","preview":"Money left is useful only when compared with work left.","explain":["Use a consistent cost basis. Estimate at completion equals actual cost to date plus the estimate to complete.","A project can look under budget because progress is also behind. Evaluate completed deliverables, not only hours charged."],"steps":["Example: direct salary budget is $40,000. Actual salary cost is $26,000.","The remaining tasks need 320 hours at $50/hour: $16,000 to finish.","Forecast total = $26,000 + $16,000 = $42,000. Forecast overrun = $2,000.","Investigate the cause. Reduce rework, rebalance tasks, or address authorized scope changes."],"question":"Only 65% of the labor budget is spent. Does that prove good performance?","answer":"No. If only half the work is complete, the remaining effort may exceed the budget.","trap":"Use remaining effort, not an optimistic guess that the team will “catch up.”","refs":["R04","R26"],"visual":null,"table":{"headers":["Item","Calculation"],"rows":[["Budget","$40,000"],["Actual","$26,000"],["Estimate to complete","320 h × $50/h = $16,000"],["Forecast total","$42,000"],["Forecast overrun","$2,000"]]}},{"id":"1.2-5","title":"Use ratios without mixing units","preview":"A ratio is a relationship—not a target for every person.","explain":["Net multiplier = net revenue ÷ direct labor cost. Utilization compares direct labor with total labor on the stated basis.","An individual time-based utilization example can use hours. A firm’s dollar-based metric must use dollars consistently. Different staff salaries make these results differ."],"steps":["Example: net revenue is $90,000 and direct labor cost is $30,000. Net multiplier = 3.0.","Total labor cost is $50,000. Dollar-based utilization = $30,000 ÷ $50,000 = 60%.","Payroll multiplier = $90,000 ÷ $50,000 = 1.8. Also: 3.0 × 0.60 = 1.8.","Use the trend to ask whether the problem is project efficiency, available work, or staffing."],"question":"For one employee, 28 project hours out of 40 paid hours gives what time-based utilization?","answer":"28 ÷ 40 = 70%. This is an hours-based calculation, not automatically the firm’s dollar-based KPI.","trap":"High utilization can still include rework. It does not prove good quality or profit.","refs":["R04"],"visual":null,"table":null}],"2.1":[{"id":"2.1-1","title":"Break the scope into a work plan","preview":"Scope says what. The work plan says how.","explain":["A work breakdown structure divides the promised outputs into manageable pieces. It is not a schedule until dates and dependencies are added.","Start with deliverables. Then list the tasks, people, inputs, review, and approval needed to produce them."],"steps":["Example: the agreed output is a coordinated permit set.","Divide it into architectural, structural, and MEP packages.","Add code review, interdisciplinary checking, corrections, and issue preparation.","Assign an owner and time allowance to each task."],"question":"Is “finish CDs by Friday” a complete work plan?","answer":"No. It omits task ownership, required inputs, review gates, and completion criteria.","trap":"A drawing list alone does not include the effort required to coordinate and approve it.","refs":["R06"],"visual":null,"table":{"headers":["Level","Example"],"rows":[["Deliverable","Permit set"],["Work package","Architectural package"],["Task","Coordinate reflected ceiling plan"],["Completion test","Lights, diffusers, access, and structure checked"]]}},{"id":"2.1-2","title":"Write a useful task card","preview":"Give each task an input, output, owner, and finish test.","explain":["A task is manageable when someone can tell whether it is ready to start and truly finished.","Include the review step. A task that consumes its entire allowance before checking is not properly budgeted."],"steps":["Example: prepare the ceiling plan.","Input: current room layout and consultant device locations.","Work: draft 12 hours; coordinate 4 hours; check and correct 4 hours.","Output: a checked sheet with logged issues resolved. Total allowance: 20 hours."],"question":"The drafter used 12 hours. Is the task complete?","answer":"No. The task card still requires coordination, checking, and corrections.","trap":"Do not define completion as “hours used.” Define the required result.","refs":["R06","R33"],"visual":null,"table":{"headers":["Field","Example entry"],"rows":[["Owner","Project architect"],["Input due","MEP layout, Tuesday"],["Output due","Checked ceiling plan, Friday"],["Acceptance","No unresolved device or access conflicts"],["Allowance","20 staff hours"]]}},{"id":"2.1-3","title":"Use phase gates","preview":"A gate is a decision point before work advances.","explain":["A phase gate checks whether the team has enough approved information to continue. Decide what evidence each gate needs.","The design can develop progressively. Unresolved issues still need an owner, impact assessment, and planned resolution date."],"steps":["Example: before moving into detailed documentation, check design approval, cost alignment, and consultant coordination.","The owner has not chosen the major HVAC system.","Identify affected space, shafts, structure, cost, and drawings.","Resolve the choice or explicitly plan the limited work that can proceed without causing avoidable rework."],"question":"Can the team simply label a phase “complete” because its calendar period ended?","answer":"No. Check the agreed deliverables and approval criteria.","trap":"A phase gate should reveal unresolved decisions, not merely collect signatures.","refs":["R32","R33"],"visual":"gates","table":null},{"id":"2.1-4","title":"Maintain a baseline and a forecast","preview":"Keep the approved plan visible while updating reality.","explain":["The baseline is the approved reference. The current forecast reflects actual progress and remaining work. Keep both.","Update assignments and forecasts as facts change. Changing the work plan does not automatically amend the fee or contract date."],"steps":["Example: the baseline requires a review on day 10. New consultant information moves the forecast to day 13.","Record the three-day difference and its cause.","Assess downstream effects and possible recovery.","Obtain necessary authorization for contractual changes. Retain the prior baseline for comparison."],"question":"Should you erase the old dates to make the variance disappear?","answer":"No. Record the approved revision and preserve the history.","trap":"A forecast is a prediction. A revised contractual commitment requires the right approval.","refs":["R06","R07"],"visual":null,"table":null}],"2.2":[{"id":"2.2-1","title":"Read a Gantt / bar schedule","preview":"The horizontal bars show when each task happens.","explain":["Read task names down the left and time across the top. A bar’s left edge is the start. Its length is the duration. Its right edge is the finish.","Overlapping bars mean concurrent work. A milestone has zero duration. A bar chart alone does not prove the dependency logic or available staffing."],"steps":["This example uses elapsed workdays, starting at day 0. A task from 0 to 2 lasts two workdays.","A: confirm brief, 2 days. B: layout, 4 days. C: consultant study, 3 days.","B and C start after A. D: coordination, 2 days, waits for both. E: review, 1 day, follows D.","Read the chart: baseline completion is day 9. Change C’s delay to see when completion moves."],"question":"B finishes on day 6. C finishes on day 5. Can coordination start on day 5?","answer":"No. Coordination requires both inputs, so it starts on day 6.","trap":"A bar’s visual length is meaningful only after you read the time scale.","refs":["R07"],"visual":"schedule","table":null},{"id":"2.2-2","title":"Trace the dependency network","preview":"Arrows show what must happen before something else.","explain":["A dependency network shows logical order. Each path is a sequence from project start to finish.","Parallel tasks do not get added together as if they were sequential. At a merge, the next task waits for the latest required predecessor."],"steps":["Path 1: A → B → D → E = 2 + 4 + 2 + 1 = 9 days.","Path 2: A → C → D → E = 2 + 3 + 2 + 1 = 8 days.","The nine-day path controls completion in this unconstrained example.","A, B, D, and E are critical. C initially has one day of total float."],"question":"Why is the project not 12 days, the sum of every activity?","answer":"B and C run at the same time. Add durations along each path, then compare paths.","trap":"The critical path is the controlling path. It is not the path with the most expensive tasks.","refs":["R07"],"visual":"network","table":null},{"id":"2.2-3","title":"Calculate the earliest dates","preview":"A forward pass answers: how soon can it finish?","explain":["Earliest start (ES) is the earliest possible start from the network logic. Earliest finish (EF) equals ES plus duration.","At a merge, use the largest predecessor EF. These examples use elapsed-time boundaries. Do not add an extra day."],"steps":["A: ES 0; duration 2; EF 2.","B: ES 2; duration 4; EF 6. C: ES 2; duration 3; EF 5.","D: ES max(6, 5) = 6; duration 2; EF 8.","E: ES 8; duration 1; EF 9."],"question":"Two predecessors finish at 7 and 11. The successor needs both and takes 3 days. What is its EF?","answer":"ES = max(7, 11) = 11. EF = 11 + 3 = 14.","trap":"Use the later predecessor at a merge, not the average finish.","refs":["R07"],"visual":null,"table":{"headers":["Task","Duration","ES","EF"],"rows":[["A","2","0","2"],["B","4","2","6"],["C","3","2","5"],["D","2","6","8"],["E","1","8","9"]]}},{"id":"2.2-4","title":"Calculate float with a backward pass","preview":"Float is room to move—not permission to ignore a deadline.","explain":["Work backward from day 9. Latest start (LS) equals latest finish (LF) minus duration. At a split, use the smallest successor LS.","Total float = LS − ES, or LF − EF. Free float is different: delay allowed without moving the earliest start of an immediate successor."],"steps":["E: LF 9, LS 8. D: LF 8, LS 6.","B: LF 6, LS 2. C: LF 6, LS 3.","A: LF min(2, 3) = 2, LS 0.","C’s total float = 3 − 2 = 1 day. All other tasks have zero float here."],"question":"Can C slip by one day without extending day-9 completion?","answer":"Yes in this example. It uses the available float. Both paths then become critical.","trap":"Real calendars, constraints, and resource conflicts can change the result. Read the question’s assumptions.","refs":["R07"],"visual":null,"table":{"headers":["Task","ES","LS","Total float"],"rows":[["A","0","0","0"],["B","2","2","0"],["C","2","3","1"],["D","6","6","0"],["E","8","8","0"]]}},{"id":"2.2-5","title":"Recognize the four relationship types","preview":"Finish-to-start is common, but not the only option.","explain":["FS: predecessor finish controls successor start. SS: predecessor start controls successor start. FF: predecessor finish controls successor finish. SF: predecessor start controls successor finish.","A lag is a waiting interval added to a relationship. Overlap requires usable partial inputs and a review of rework risk."],"steps":["FS example: issue the coordinated set after the final check finishes.","SS example: start weekly cost tracking when design starts.","FF example: final issue logging cannot finish before final review finishes.","SF is uncommon: an existing monitoring shift cannot finish until its replacement starts."],"question":"“Start B two days after A starts” describes what?","answer":"Start-to-start with a two-day lag. It does not mean B waits for A to finish.","trap":"A logical overlap is not evidence that one person can perform two full-time tasks.","refs":["R07"],"visual":null,"table":{"headers":["Link","Controlled event","Memory aid"],"rows":[["FS","Finish → start","Finish first, then begin"],["SS","Start → start","Beginnings linked"],["FF","Finish → finish","Endings linked"],["SF","Start → finish","Replacement begins before release"]]}},{"id":"2.2-6","title":"Resolve people and calendar limits","preview":"A logical schedule can still be impossible to staff.","explain":["Check work calendars, holidays, owner decisions, authority reviews, and actual staff availability. Duration is elapsed time. Effort is staff hours.","Resource leveling moves work to fit capacity and can extend completion. Adding people only helps tasks that can be divided effectively."],"steps":["In the example network, B and C both need the same specialist full time.","They cannot run in parallel with that staffing assumption.","If B runs first, C finishes at day 9. D and E then finish at day 12.","Consider another qualified person or a justified sequence change. Preserve necessary review."],"question":"Does a five-day task always require 40 staff hours?","answer":"No. It might include waiting or part-time effort. The task’s resource loading defines hours.","trap":"An imposed deadline does not create missing capacity.","refs":["R07"],"visual":"capacity","table":null},{"id":"2.2-7","title":"Recover a delay intelligently","preview":"Shorten the controlling work and recheck every path.","explain":["Crashing adds resources or cost to shorten suitable activities. Fast-tracking overlaps work that was planned sequentially. Both have limits.","First verify the delay cause, remaining duration, and controlling path. Recalculate after each change. A different path may become critical."],"steps":["Original paths are 9 and 8 days. Reduce B from 4 days to 2.","Path A–B–D–E becomes 7 days. A–C–D–E remains 8.","New project duration is 8 days, not 7.","The change saves one project day even though B was shortened by two."],"question":"What must you check before starting detailed design with incomplete owner decisions?","answer":"Which inputs are stable, which work may be repeated, and whether the team accepts the cost and risk.","trap":"Shortening a noncontrolling activity may save zero project time.","refs":["R07"],"visual":null,"table":null},{"id":"2.2-8","title":"Read a progress line / S-curve","preview":"This line shows accumulated progress, not task sequence.","explain":["A Gantt chart shows task timing. A progress curve plots cumulative effort, cost, or earned progress over time. Read the axis labels first.","An actual spending line above a plan can mean overspending. It can also reflect more completed work. Compare scope-based progress before concluding."],"steps":["This teaching chart compares cumulative planned progress with completed progress, measured on the same defined basis.","At week 3, planned progress is 60%. Completed progress is 40%.","The gap is 20 percentage points, not automatically 20% extra time.","Review the remaining activities to predict a new completion date."],"question":"Does a 20-point progress gap prove a two-week delay?","answer":"No. The network, remaining durations, and resources determine the finish forecast.","trap":"Cost spent is not the same as work earned. Avoid comparing different measures.","refs":["R07","R26"],"visual":"curve","table":null},{"id":"2.2-9","title":"Update the schedule without hiding delay","preview":"Record actuals, remaining work, and the new forecast.","explain":["Use a status date: the cutoff for reporting progress. Record actual starts and finishes before forecasting the future.","Update remaining duration from the work still required. Preserve the approved baseline and document proposed changes."],"steps":["At day 4, B has two days remaining. C is waiting for an owner decision.","Identify when that decision can arrive and whether C’s remaining duration changes.","Recalculate coordination and review dates. Compare the finish with the baseline.","Assign a person to the missing decision. Report impact and recovery options."],"question":"Should the PM label a four-day task 75% complete solely because three days passed?","answer":"No. Verify the actual output and remaining effort.","trap":"A percentage without evidence can hide unfinished coordination and checking.","refs":["R07"],"visual":null,"table":null}],"2.3":[{"id":"2.3-1","title":"Choose the right communication channel","preview":"Match the message to its purpose and authority.","explain":["A meeting coordinates. A decision record preserves an approval. An RFI asks for information. A formal notice follows a contract process.","Record who needs to act, by when, and why. Important verbal directions need a usable written record."],"steps":["Example: a consultant needs a ceiling-height decision by Thursday.","Send the decision request to the authorized decision-maker.","State the options and the effects on cost, ducts, and schedule.","Record the approved result and distribute it to affected disciplines."],"question":"Is a copied email proof that everyone approved the change?","answer":"No. Identify the person with authority and obtain the required response.","trap":"Communication can transmit a decision; it does not create authority.","refs":["R06","S06"],"visual":null,"table":{"headers":["Need","Useful record"],"rows":[["Discuss alternatives","Meeting agenda + minutes"],["Ask a design question","RFI or issue record"],["Approve owner scope","Authorized change record"],["Preserve a contractual right","Required formal notice"]]}},{"id":"2.3-2","title":"Make minutes produce action","preview":"A useful meeting record has an owner and a due date.","explain":["Separate decisions from open actions. Include the relevant document revision so readers know what was discussed.","Circulate promptly. Correct disputed entries. Follow up on open actions rather than assuming silence closes them."],"steps":["Weak entry: “MEP to coordinate.”","Better: “MEP lead to confirm shaft size by Oct 20; architecture to update plan after confirmation.”","Log the decision on shaft location separately.","At the next meeting, check the actual revised drawings before marking the item closed."],"question":"What two fields make an action easier to manage?","answer":"A named responsible person and a specific due date. Add the required output and dependencies.","trap":"Minutes should not imply approval when the discussion produced only a recommendation.","refs":["R06"],"visual":null,"table":{"headers":["ID","Action","Owner","Due","Status"],"rows":[["M-12","Confirm shaft dimensions","MEP lead","Oct 20","Open"],["M-13","Update floor opening","Architect","After M-12","Waiting"],["D-04","Shaft location approved","Owner rep","Oct 17","Decision recorded"]]}},{"id":"2.3-3","title":"Close the RFI loop","preview":"A clarification may reveal a change, but is not automatically one.","explain":["Read the question, relevant drawings, specifications, and contract terms. Coordinate the answer with affected disciplines.","If the response changes scope, price, or time, route that impact through the appropriate process. Track the answer into the current documents."],"steps":["Example: an RFI identifies two different equipment clearances.","Check the manufacturer requirement and the contract documents.","Issue a coordinated response and evaluate any change impact.","Update the issue log and affected sheets so the conflict does not remain elsewhere."],"question":"Does every RFI entitle the contractor to additional payment?","answer":"No. Determine the requirement and cause. Entitlement depends on the contract and facts.","trap":"Answering quickly is not enough if the answer creates a second conflict.","refs":["R15","R24"],"visual":null,"table":null},{"id":"2.3-4","title":"Escalate with facts","preview":"Say what is missing, its impact, and the needed decision.","explain":["Escalation moves an unresolved issue to someone who can act. Use the agreed communication route.","For formal notices, verify recipient, delivery method, trigger, and deadline. A normal email thread may be insufficient."],"steps":["Example: owner approval is four days late.","Record when approval was requested and which work is blocked.","State a required response date and the current schedule impact.","Offer viable choices. Send any separate contractual notice as required."],"question":"What is more useful than “the owner is delaying us”?","answer":"“Approval X is outstanding. It blocks task Y. Please decide by date Z; the current finish impact is three workdays.”","trap":"Do not confuse a management reminder with a legally sufficient Claim notice.","refs":["S06","R11"],"visual":null,"table":null}],"3.1":[{"id":"3.1-1","title":"Draw who hired whom","preview":"Contract lines establish duties and authority.","explain":["In a conventional design–bid–build arrangement, the owner contracts separately with the architect and contractor. The architect hires its own consultants.","B101 governs owner–architect services. A101 provides owner–contractor business terms. A201 provides construction conditions. C401 aligns architect–consultant services."],"steps":["Example: the contractor asks the architect to direct a subcontractor’s crew.","Trace the contract lines. The contractor manages the trade’s construction work.","The architect communicates design requirements within its administration role.","Route construction direction through the contractor and the applicable contract procedure."],"question":"Does administering A201 make the architect a party to the owner–contractor agreement?","answer":"No. The architect’s service agreement requires agreed administration. That does not create a new contracting party.","trap":"Being involved in a process is different from being responsible for every part of it.","refs":["S05","R12","R13"],"visual":"contracts","table":null},{"id":"3.1-2","title":"Sort the services before pricing","preview":"Basic, supplemental, and additional describe different scope situations.","explain":["Read the selected service provisions, exclusions, and exhibits. A familiar label does not guarantee a particular service is included.","Supplemental services are identified at signing. Additional services arise as the project proceeds. Follow the agreement’s notice and authorization rules."],"steps":["Example: programming is selected in the supplemental-services table at signing. Budget it in the agreed scope.","Later, the owner changes the approved room count. Identify resulting redesign tasks.","Check whether the change triggers an additional-service provision.","Document fee and time impacts before proceeding as required by the contract."],"question":"Is any request made after signing automatically an additional service?","answer":"No. It may already be included, or may involve correcting the architect’s own work. Read the trigger.","trap":"A late request and an extra-service entitlement are not synonyms.","refs":["R10","S04"],"visual":null,"table":{"headers":["Situation","Starting question"],"rows":[["Selected specialty at signing","Who was assigned this supplemental service?"],["New owner requirement","Does it change the agreed baseline?"],["Correction of own deficient work","Who bears the correction obligation?"],["Extra site visits","What frequency or limit was agreed?"]]}},{"id":"3.1-3","title":"Manage the owner’s inputs and decisions","preview":"Missing information can affect more than one phase.","explain":["Identify the owner’s required information, consultants, approvals, and budget decisions. Put them in the work plan with due dates.","For B101, review the initial information and owner responsibilities together. Material changes can affect services, schedule, and compensation."],"steps":["Example: the owner’s survey arrives after grading design was scheduled to start.","Identify which tasks need verified elevations and boundaries.","Notify the owner of the missing input and resulting impacts.","Resequence unaffected tasks. Avoid presenting assumed data as verified facts."],"question":"Can the PM silently assume a missing boundary location to meet the issue date?","answer":"No. Resolve the missing information and document any agreed assumptions or limits before relying on them.","trap":"A deadline does not make an unknown site condition known.","refs":["R11","S02"],"visual":null,"table":null},{"id":"3.1-4","title":"Respond to budget trouble under the agreement","preview":"The right response depends on timing and cause.","explain":["Design-phase cost monitoring and a high bid are related but distinct situations. Read the applicable B101 provision and any amendment.","The architect makes recommendations when its estimate exceeds budget. The 2017 form includes a redesign compensation exception for market conditions that could not reasonably be anticipated."],"steps":["Example: the design estimate rises after the owner adds premium finishes.","Reconcile the change with the approved scope and budget.","Present adjustments to size, quality, scope, or budget for the owner’s decision.","If bids later exceed budget, evaluate that separate trigger under the agreement."],"question":"Should you answer “redesign is always free” without reading the facts?","answer":"No. Check the clause, cause, edition, and amendments.","trap":"An estimate is professional judgment. It is not an unconditional guarantee of market bids.","refs":["R10","R25"],"visual":null,"table":null},{"id":"3.1-5","title":"Read the clauses that survive a dispute","preview":"Payment, licenses, suspension, and remedies connect.","explain":["A service agreement also addresses use of drawings, payment, disputes, suspension, and termination. Read these as connected procedures.","A project-use license is different from copyright ownership. Ending services may leave some obligations in effect."],"steps":["Example: an owner stops paying and asks for all files for a replacement architect.","Check payment obligations and required notices.","Review suspension or termination rights and the license conditions.","Preserve records. Use the agreed dispute process and appropriate professional advice for actual disputes."],"question":"Does paying an invoice automatically transfer the copyright?","answer":"No. Identify the ownership and license terms in the agreement.","trap":"Do not assume nonpayment permits immediate action without the required notice.","refs":["S01","S02","R10"],"visual":null,"table":null}],"3.2":[{"id":"3.2-1","title":"Make the consultant scope support the prime","preview":"A promise upstream needs a workable obligation downstream.","explain":["The prime agreement is the owner–architect agreement referenced in C401. Applicable duties flow through to consultant services.","Compare actual scopes, exclusions, standards, deliverables, and deadlines. Do not rely on the form number alone."],"steps":["Example: the architect promises energy modeling, but no consultant proposal includes it.","Identify the missing service before signing the consultant agreement.","Assign responsibility and agree on inputs, outputs, fee, and due date.","Update the scope matrix so the service is not lost between contracts."],"question":"Does incorporating the prime agreement solve every scope gap?","answer":"No. The specific services and interfaces still need to be coordinated.","trap":"A broad coordination clause is not a substitute for a defined deliverable.","refs":["R12"],"visual":null,"table":null},{"id":"3.2-2","title":"Build a consultant issue calendar","preview":"Input dates must leave time for your review.","explain":["Work backward from the coordinated issue date. Include receipt, interdisciplinary review, correction, and final checking.","Ask what content is required at each milestone. A preliminary file may not contain final loads, dimensions, or details."],"steps":["Example: the coordinated package is due day 20.","Reserve days 18–19 for final checking and day 20 for release.","Require corrected consultant files by day 17.","Set initial consultant issue for day 13 so days 14–16 can support review and corrections."],"question":"A consultant proposes delivery on day 20. Is it aligned with the coordinated issue?","answer":"No. It leaves no time to review and incorporate that information.","trap":"Matching the final date is not the same as supporting the final date.","refs":["R06","R07"],"visual":null,"table":{"headers":["Milestone","Example day"],"rows":[["Initial consultant issue","13"],["Interdisciplinary review + corrections","14–16"],["Corrected files received","17"],["Final check","18–19"],["Coordinated release","20"]]}},{"id":"3.2-3","title":"Define the handoff between disciplines","preview":"A shared interface needs a shared check.","explain":["Each consultant remains responsible for its agreed professional services. The architect coordinates the overall integration within its scope.","List critical interfaces: openings, loads, clearances, elevations, controls, and access. Define the information needed on each side."],"steps":["Example: a rooftop unit affects structure, roof details, power, and drainage.","MEP confirms weight, size, and connections.","Structure verifies supports. Architecture coordinates curb, waterproofing, and access.","Close the issue only after the affected documents agree."],"question":"Who fixes a structural calculation error?","answer":"The responsible structural professional. The PM coordinates the effect on other work and tracks closure.","trap":"Coordination does not mean the architect independently redesigns every consultant system.","refs":["R12","R33"],"visual":null,"table":{"headers":["Interface","Information needed"],"rows":[["MEP → structure","Loads + support locations"],["Structure → architecture","Opening sizes + framing"],["Architecture → MEP","Ceiling heights + access zones"],["All → PM","Current coordinated revision"]]}},{"id":"3.2-4","title":"Control consultant changes and digital reliance","preview":"Align scope, compensation, file use, and responsibilities.","explain":["Identify consultant impacts when the owner changes the project. Review payment conditions and the consultant amendment process.","For digital exchanges, define file purpose, status, coordinates, and permitted reliance. A model may be suitable for coordination but unsuitable for fabrication."],"steps":["Example: the owner relocates a mechanical room after approval.","Ask MEP and structure to identify additional tasks and schedule effects.","Coordinate those impacts with the architect’s proposal and required authorization.","Issue a dated model status and archive superseded files."],"question":"Can a recipient assume every model element is fabrication-ready?","answer":"No. Confirm the agreed model use and reliance protocols.","trap":"Indemnity and a duty to defend are different obligations. Read the actual provision.","refs":["R12","R28","R30"],"visual":null,"table":null}],"3.3":[{"id":"3.3-1","title":"Separate delivery method from payment method","preview":"Who contracts with whom is different from how they are paid.","explain":["Delivery describes relationships and how work is organized. Compensation describes the price mechanism.","A stipulated sum is an agreed price for the stated scope. Cost-plus reimburses defined costs plus a fee. A GMP limits payment as defined, subject to permitted adjustments."],"steps":["Example: a CM as constructor works under cost-plus with a GMP.","Identify its preconstruction and construction duties under A133.","Read what costs, allowances, contingencies, and changes are included.","Do not assume the architect’s fee is part of the contractor’s GMP."],"question":"Does “design-build” automatically tell you whether the price is lump sum or cost-plus?","answer":"No. Read the design-build agreement’s compensation terms.","trap":"A maximum price is not protection against every owner change.","refs":["R08","R13","R16","R17"],"visual":null,"table":{"headers":["Question","Look for"],"rows":[["Who holds design + construction?","Delivery structure"],["What is reimbursable?","Cost definition"],["What is the fee?","Compensation clause"],["Can the cap change?","Permitted adjustments + amendment"]]}},{"id":"3.3-2","title":"Respect the contractor’s construction role","preview":"Review does not transfer means, methods, or trade coordination.","explain":["The contractor reviews and coordinates submittals before sending them forward. The architect’s review has a defined design-related purpose.","Construction supervision, sequencing, and safety responsibilities do not transfer merely because the architect visits the site or reviews a submittal."],"steps":["Example: a steel shop drawing arrives without contractor review.","Check the agreed submittal process.","Return or route it for the required contractor review before architectural review.","If a design deviation is proposed, evaluate it through the appropriate approval process."],"question":"Does an architect’s review remove the contractor’s duty to verify field dimensions?","answer":"No. Those responsibilities remain allocated by the contract.","trap":"Do not treat shop drawings as a way to silently change contract requirements.","refs":["R24","R15"],"visual":null,"table":null},{"id":"3.3-3","title":"Calculate a payment application","preview":"Earned value, retainage, and earlier certificates each matter.","explain":["G703 supports the line items. G702 summarizes the application and certificate. Use the contract’s rules for eligible work, stored materials, and retainage.","The architect evaluates certification. The owner pays under the contract. Application and certification amounts may differ."],"steps":["Example: eligible completed work and stored material total $200,000. Assume 10% retainage applies to that entire amount.","Retainage = $20,000. Earned less retainage = $180,000.","Prior payment certificates total $135,000.","Current amount = $180,000 − $135,000 = $45,000, before other stated adjustments."],"question":"Why not pay the whole $180,000 again?","answer":"That would include value already certified. Subtract the previous certificates.","trap":"Retainage rules can differ by work and stored materials. Use the stated terms.","refs":["R23","R14"],"visual":null,"table":{"headers":["Step","Amount"],"rows":[["Eligible cumulative value","$200,000"],["Less retainage","− $20,000"],["Less prior certificates","− $135,000"],["Current application amount","$45,000"]]}},{"id":"3.3-4","title":"Separate substantial and final completion","preview":"A usable building can still have unfinished items.","explain":["Substantial completion concerns readiness for the intended use under the contract. Final completion includes completing remaining obligations.","Track the completion date, outstanding items, assigned responsibilities, warranties, and closeout documentation. Check requirements for the specific work or portion."],"steps":["Example: the building can be used, but a few approved touch-up items remain.","Evaluate whether those items prevent intended use or required approvals.","Document substantial completion if the contract criteria are met.","Track each remaining item and required closeout document to final completion."],"question":"Does a zero-item punch list define every substantial completion?","answer":"No. The intended-use standard and actual contract requirements control.","trap":"Substantial completion, occupancy approval, and final payment are related but distinct events.","refs":["R22","S07"],"visual":null,"table":{"headers":["Event","What to establish"],"rows":[["Substantial completion","Ready for intended use under the contract"],["Authority occupancy approval","Applicable legal permission to occupy"],["Final completion","Remaining contractual work completed"],["Final payment","Payment prerequisites satisfied"]]}},{"id":"3.3-5","title":"Choose the right change document","preview":"First ask whether work, price, and time are agreed.","explain":["Use the state of the decision to select the instrument. A pricing request gathers information. A change order records an agreement.","A directive can authorize work before price or time is fully agreed. Minor-change authority is limited to no adjustment in sum or time."],"steps":["Example: the owner wants a revised entrance. Price is not yet known. Request a proposal first.","If all required parties agree on scope, sum, and time, prepare a change order.","If authorized work must proceed before agreement, evaluate the directive procedure.","Do not label a cost-bearing change as a minor instruction."],"question":"A G709 describes the revised entrance. May the contractor treat it as direction to build?","answer":"No. It requests a proposal, not permission to proceed.","trap":"A form’s title cannot cure missing authority or signatures.","refs":["R18","R19","R20","R21"],"visual":"change","table":null}],"3.4":[{"id":"3.4-1","title":"Identify an owner-hired consultant","preview":"Coordination does not change who holds the agreement.","explain":["An owner-retained consultant contracts with the owner. The architect still needs usable information to integrate the project.","Read B101’s allocation of owner and architect responsibilities. Obtain the scope information needed to coordinate services."],"steps":["Example: the owner hires a geotechnical engineer directly.","The architect identifies when foundation design needs the report.","If the report is late, notify the owner and explain the affected work.","Do not unilaterally change the engineer’s contract or present missing recommendations as confirmed."],"question":"Who normally authorizes a fee change to the owner’s consultant?","answer":"The owner or its authorized representative, under that consultant’s agreement.","trap":"The PM’s coordination role does not create unlimited authority over the owner’s contracts.","refs":["S02","R31"],"visual":"owner-consultant","table":null},{"id":"3.4-2","title":"Schedule owner information as real tasks","preview":"An external input belongs on the project schedule.","explain":["Treat surveys, equipment data, testing, and commissioning inputs as dependencies. Name the provider and required content.","A due date should leave time to review and use the information. Record what happens if it is late or incomplete."],"steps":["Example: a food-service vendor must supply utility requirements before MEP design.","Require a complete equipment schedule, not just marketing brochures.","Set an input date before the MEP coordination milestone.","Track outstanding data and notify the owner of the impact."],"question":"Can “owner to provide” be left without a due date?","answer":"It can appear in a contract, but the work plan still needs a usable date and follow-up owner.","trap":"A missing external input can sit on the critical path.","refs":["R06","R31"],"visual":null,"table":null},{"id":"3.4-3","title":"Resolve conflicting consultant inputs","preview":"Identify the conflict before choosing a version.","explain":["Check author, issue date, assumptions, and document status. A newer file is not necessarily an approved revision.","Coordinate resolution through the responsible professionals and the owner. Record the controlling decision and update affected outputs."],"steps":["Example: survey and civil files show different site elevations.","Compare benchmarks, coordinates, and stated datums.","Ask the responsible parties to resolve the discrepancy.","After resolution, recheck grades, entries, utilities, and foundation elevations."],"question":"Should the architect simply use the higher elevation as a precaution?","answer":"No. Resolve the basis. An arbitrary choice can create access, drainage, or structural conflicts.","trap":"Data integration requires compatible reference systems, not just matching file formats.","refs":["R28","R30"],"visual":null,"table":null},{"id":"3.4-4","title":"Close the owner-input loop","preview":"Confirm receipt, review, integration, and remaining limits.","explain":["Track an input beyond “received.” It may still need review, clarification, or incorporation.","If a required service is absent, document the need and ask the owner to provide or authorize it through the agreement."],"steps":["Example: a commissioning report identifies a control sequence issue.","Assign the design response to the appropriate engineer.","Track the correction into drawings and specifications.","Confirm the owner receives the resolved record and any remaining operational action."],"question":"Is uploading a report enough to close the issue?","answer":"No. Verify that its relevant findings have been reviewed and acted on.","trap":"A report can be complete while the project response remains incomplete.","refs":["R31","R33"],"visual":null,"table":{"headers":["Status","Meaning"],"rows":[["Requested","Required input identified"],["Received","File delivered"],["Reviewed","Adequacy and conflicts checked"],["Integrated","Affected documents updated"],["Closed","Result verified; remaining actions assigned"]]}}],"4.1":[{"id":"4.1-1","title":"Separate three different budgets","preview":"Construction cost, total project cost, and your service fee differ.","explain":["Construction budget addresses the work being built. Total project budget can also include land, financing, professional fees, and other owner costs.","Your internal service budget addresses staff time and expenses needed to deliver your agreement. Keep the bases visible in every comparison."],"steps":["Example: owner total budget is $5 million. Of this, $4 million is allocated to construction.","A $4.2 million construction estimate exceeds the construction allocation by $200,000.","It is not under budget merely because $4.2 million is less than $5 million.","Identify which budget the question asks you to monitor."],"question":"Can unused architectural staff hours automatically fund higher contractor costs?","answer":"No. Those are different budget and contract relationships.","trap":"Never compare a construction-only estimate with a total-project figure without reconciling scope.","refs":["R25","S02"],"visual":"budgets","table":null},{"id":"4.1-2","title":"Compare estimates on the same basis","preview":"Explain the difference before cutting scope.","explain":["Reconcile area, quantities, systems, location, pricing date, exclusions, allowances, escalation, and contingencies.","A comparison is meaningful only when the cost bases match. Separate a scope change from a pricing change."],"steps":["Example: estimate A is $3.80 million and excludes site work. Estimate B is $4.05 million and includes $300,000 of site work.","Remove B’s site-work allowance for the comparison: $4.05m − $0.30m = $3.75m.","On that limited common basis, B is $50,000 lower.","Do not conclude B is $250,000 more expensive without this reconciliation."],"question":"What should be the first response to conflicting estimates?","answer":"Compare assumptions, inclusions, and quantities before deciding which number is reliable.","trap":"A lower estimate can simply omit required work.","refs":["R26"],"visual":null,"table":{"headers":["Estimate","Reported","Site work","Comparable building cost"],"rows":[["A","$3.80m","Excluded","$3.80m"],["B","$4.05m","$0.30m included","$3.75m"]]}},{"id":"4.1-3","title":"Calculate the gap and evaluate options","preview":"Use a cost decision that preserves required performance.","explain":["Budget variance is the difference between forecast and budget. State whether a positive value means overrun in your calculation.","Evaluate proposed savings against code, owner goals, lifecycle effects, coordination, and schedule. A cheaper material may shift cost elsewhere."],"steps":["Example: construction budget $4.0m; forecast $4.3m. Overrun = $0.3m.","Percentage over budget = $0.3m ÷ $4.0m = 7.5%.","Option A saves $180,000 but adds $30,000 of related work. Net saving = $150,000.","Remaining gap = $150,000. Present complete options for an authorized owner decision."],"question":"Does a claimed $180,000 product saving close a $180,000 budget gap?","answer":"Only if related costs and other impacts do not reduce that saving.","trap":"Value evaluation considers performance and total effects, not just first cost.","refs":["R25","R26"],"visual":null,"table":null},{"id":"4.1-4","title":"Track uncertainty and forecast change","preview":"A contingency is an allowance for uncertainty, not free scope.","explain":["Identify who controls each contingency and what it covers. Avoid counting the same risk in multiple allowances without recognizing it.","Escalation addresses pricing changes over time. Update assumptions as scope and procurement dates become clearer."],"steps":["Example: an estimate has $100,000 of identified contingency. A new owner feature costs $80,000.","Check whether that feature is an authorized scope change and whether using the allowance is appropriate.","Record the remaining uncertainty after any decision.","Continue milestone cost checks; do not wait until bidding to discover a trend."],"question":"Does using contingency prove there is no budget risk left?","answer":"No. The allowance may shrink while unresolved risks remain.","trap":"Do not hide a scope increase inside a cost allowance.","refs":["R26","R25"],"visual":null,"table":null}],"4.2":[{"id":"4.2-1","title":"Tell scope change from scope creep","preview":"Small requests can add up to a large obligation.","explain":["A scope change alters the agreed services or project requirements. Scope creep is uncontrolled accumulation of such changes.","Compare the request with the agreement and approved decisions. Distinguish a new owner requirement from correction of deficient work."],"steps":["Example: six “small” owner changes each require 8 staff hours.","Total effort = 6 × 8 = 48 hours.","At a stated billing rate of $150/hour, potential fee impact is $7,200, subject to the agreement.","Assess the combined effect on consultants, deadlines, and deliverables."],"question":"Does an informal request count as no change because it was made during a meeting?","answer":"No. Assess its substance and follow the authorization process.","trap":"Size and informality do not determine whether work is included.","refs":["R11","R05"],"visual":null,"table":null},{"id":"4.2-2","title":"Document impact before committing","preview":"Connect the request to tasks, cost, time, and approvals.","explain":["A change assessment should identify the trigger, affected scope, fee basis, consultant effects, schedule, and required approval.","Use the governing agreement’s notice rules. Do not promise a new deadline before checking dependencies and capacity."],"steps":["Example: moving a stair affects plans, structure, egress review, and MEP routing.","List each discipline’s added work and review time.","Identify whether approvals must be resubmitted.","Present the coordinated proposal and obtain required authorization."],"question":"Why is the drafting estimate alone insufficient?","answer":"The change may also require engineering, code review, coordination, and authority review.","trap":"A change to one drawing can affect several contracts and approvals.","refs":["R11","R06"],"visual":null,"table":{"headers":["Impact","Question to answer"],"rows":[["Scope","Which deliverables change?"],["Fee","What extra services and expenses?"],["Time","Which dependencies move?"],["Quality","What must be rechecked?"],["Authority","Who can approve and how?"]]}},{"id":"4.2-3","title":"Distinguish service changes from construction changes","preview":"An extra-service agreement is not a contractor change order.","explain":["The architect’s fee is governed by its service agreement. Contractor scope, sum, and time are governed by the construction agreement.","One owner request can affect both. Manage each relationship with the appropriate notice, proposal, and authorization."],"steps":["Example: the owner adds a room during construction.","The architect evaluates additional design services.","The contractor provides the construction price and time impact.","Coordinate the approvals. Do not assume approval of one fee authorizes the other work."],"question":"Does signing a contractor change order automatically approve the architect’s additional-service fee?","answer":"Not automatically. Check the owner–architect agreement and its authorization requirements.","trap":"Separate contract relationships require separate consideration.","refs":["R10","R21"],"visual":"change","table":null},{"id":"4.2-4","title":"Maintain a change log","preview":"Track requests through decision, issue, and verification.","explain":["A change log makes pending scope visible. Include the baseline reference, requester, status, impact, decision, and affected documents.","After approval, update the work plan, budget, schedule, and documents. Verify downstream coordination."],"steps":["Example: C-07 requests moving the reception desk.","Status begins “under review,” not “approved.”","After authorization, record the decision date and required revisions.","Close only after the current documents show the coordinated result."],"question":"When should a rejected request disappear from the log?","answer":"It should remain recorded as rejected, with the decision and date. Preserve the history.","trap":"A request, recommendation, and approval are different statuses.","refs":["R06","R11"],"visual":null,"table":{"headers":["ID","Request","Impact","Status"],"rows":[["C-07","Move reception","24 h + electrical revision","Awaiting authorization"],["C-08","Change room name","No stated fee/time effect","Issued"],["C-09","Add service entrance","Budget + permit review","Rejected; reason recorded"]]}}],"4.3":[{"id":"4.3-1","title":"Document design–bid–build","preview":"Coordinate the package bidders must price.","explain":["In conventional DBB, the owner holds separate design and construction contracts. Design documents support procurement and subsequent construction.","Coordinate drawings, specifications, schedules, and procurement information. Track addenda during bidding and modifications after contract execution."],"steps":["Example: a finish changes during bidding.","Identify every affected drawing and specification.","Issue the clarification through the required bidding process to the relevant bidders.","After award, manage further changes through the construction contract procedure."],"question":"Should an important bid clarification be sent privately to only one bidder?","answer":"Follow the procurement rules. The bid information needs controlled, fair distribution.","trap":"A bid-phase addendum and a construction-phase change order serve different stages.","refs":["R08","S12","R13"],"visual":"delivery","table":null},{"id":"4.3-2","title":"Plan CM and phased bid packages","preview":"Early release requires clear boundaries and coordination.","explain":["CM as constructor provides early input and later construction under its agreement. CM as adviser is a different relationship.","Fast-track or phased packages overlap design and construction. Define what is included, what remains unresolved, and how later work connects."],"steps":["Example: foundations are released before the superstructure design is complete.","Verify the loads and design assumptions needed for the foundations.","Identify later decisions that could invalidate those assumptions.","Coordinate interface responsibility, review, and change control before release."],"question":"Does an early package eliminate the need to coordinate with unfinished later packages?","answer":"No. Early commitments can increase the cost of later changes.","trap":"Speed gained by overlap can be lost through rework at package interfaces.","refs":["R16","R08"],"visual":null,"table":null},{"id":"4.3-3","title":"Adapt to design-build and IPD","preview":"Use the relationships and scope of the selected family.","explain":["Design-build places design and construction responsibility with one entity under the owner’s agreement. The design-builder may hire the architect.","IPD describes collaborative approaches with different contract models. Transitional agreements do not automatically create a single shared-risk entity."],"steps":["Example: the architect is hired under B143 for preliminary design only.","Check which services were selected. Identify who completes later documentation and administration.","Agree on the handoff information and responsibilities.","Do not import the entire B101 scope into that limited appointment."],"question":"Does “IPD” alone identify the exact compensation and risk-sharing arrangement?","answer":"No. Read the actual agreement family and selected terms.","trap":"A delivery label is only the start of the contract analysis.","refs":["R17","S13","S14","S15"],"visual":null,"table":{"headers":["Delivery","Relationship to identify"],"rows":[["DBB","Owner–architect; owner–contractor"],["CM as constructor","Owner–CM; owner–architect"],["Design-build","Owner–design-builder; design-builder–architect as applicable"],["Transitional IPD","Coordinated separate agreements using A295"]]}},{"id":"4.3-4","title":"Control revisions and model use","preview":"Everyone needs the current authorized information.","explain":["Use file names, issue dates, revision identifiers, transmittals, and controlled locations. Keep superseded information identifiable.","For models, define purpose, reliability, exchange format, coordinates, and permitted reliance. A detailed-looking object may still be provisional."],"steps":["Example: revision 4 changes a duct route.","Publish a coordinated package and identify affected sheets and models.","Notify the people who need it. Archive revision 3 as superseded.","Check whether specifications, structural openings, and ceilings also changed."],"question":"Does “latest upload” always mean “authorized for construction”?","answer":"No. Check issue purpose, status, and the contract’s document-control process.","trap":"Visual detail is not proof of model maturity or approved use.","refs":["R28","R30"],"visual":null,"table":{"headers":["Control","Example"],"rows":[["Identifier","M-102 Rev 4"],["Status","Issued for coordination"],["Transmittal","Purpose, recipients, date, affected files"],["Archive","Prior revision retained and marked superseded"],["Reliance","Coordination use; not fabrication authorization"]]}}],"4.4":[{"id":"4.4-1","title":"Map the authorities","preview":"One project can need several independent approvals.","explain":["An authority having jurisdiction (AHJ) applies a particular set of legal requirements. Different agencies may review different aspects of the same project.","Identify applicable reviewers, submissions, dependencies, fees, and timelines. Confirm actual local requirements."],"steps":["Example: a restaurant may need zoning, building, fire, health, and utility reviews.","Record who reviews what and which approval depends on another.","Assign a team member to each submission.","Track conditions and resubmission dates separately."],"question":"Does zoning approval automatically establish fire approval?","answer":"No. They cover different requirements and may use separate processes.","trap":"Do not report “approved” without identifying the authority and scope.","refs":["R36","R37"],"visual":null,"table":{"headers":["Example reviewer","Typical focus to verify locally"],"rows":[["Zoning","Use, setbacks, height, parking"],["Building","Adopted building code compliance"],["Fire","Fire protection and access"],["Health","Food-service requirements"],["Utility","Service connection requirements"]]}},{"id":"4.4-2","title":"Build an approval schedule","preview":"Include reviews, corrections, and resubmittals.","explain":["A submission date is not an approval date. Ask about review cycles and required completeness checks.","Allow time for team responses and coordination. Some approvals are parallel; others depend on prior decisions."],"steps":["Example assumption: first review takes 15 workdays. Team response takes 5. Resubmittal review takes 10.","Total sequential duration = 15 + 5 + 10 = 30 workdays.","A 20-workday allowance leaves a 10-day gap under these assumptions.","Recheck the actual process and schedule risk before promising the start date."],"question":"Can the PM recover agency review time simply by assigning another drafter?","answer":"Not necessarily. Staff can help the response, but the external review duration is a separate constraint.","trap":"Use stated or verified durations; this teaching example is not a jurisdiction’s promised turnaround.","refs":["R07","R36"],"visual":"approvals","table":null},{"id":"4.4-3","title":"Answer review comments with evidence","preview":"Every comment needs a disposition and a traceable revision.","explain":["Use a response matrix. Quote or identify the comment, name the responder, describe the action, and reference the revised document.","Coordinate responses across disciplines. One correction can create a conflict on another sheet."],"steps":["Example: comment 12 asks for accessible door clearance.","The architect revises the plan and identifies the sheet/detail.","Check the wall, door hardware, and adjacent equipment for consistency.","Submit the response and track whether the authority accepts it."],"question":"Is “addressed” an adequate response by itself?","answer":"No. Show what changed and where it can be verified.","trap":"A submitted response is not yet an accepted response.","refs":["R36","R37"],"visual":null,"table":{"headers":["Comment","Responsible","Response","Status"],"rows":[["12: door clearance","Architect","Plan A-101 revised; detail 5 added","Resubmitted"],["18: fire system note","Fire engineer","Specification cross-reference corrected","Awaiting review"]]}},{"id":"4.4-4","title":"Track conditions after approval","preview":"Later revisions can trigger new reviews.","explain":["Read approval conditions and deferred requirements. Determine what must be complete before permit issuance, construction, or occupancy.","Assess whether a design change requires revised documents or renewed approval. Do not assume a previous stamp covers changed work."],"steps":["Example: an approved corridor is narrowed by a later owner request.","Recheck applicable requirements and the permit documents.","Coordinate any necessary resubmittal with the authority.","Track the revision through approval and release before relying on it."],"question":"Does the owner’s approval remove the need for an authority’s approval?","answer":"No. They address different responsibilities.","trap":"A permit is not a blanket waiver for future design changes.","refs":["R36","R37"],"visual":null,"table":null}],"5.1":[{"id":"5.1-1","title":"Establish the code basis early","preview":"Know the adopted rules before checking details.","explain":["Identify jurisdiction, adopted editions, amendments, and applicable project conditions. Building use, scope, and existing conditions affect requirements.","Record the basis and assign qualified people to analysis and review. This lesson teaches the management process, not a universal code solution."],"steps":["Example: an existing retail space becomes a restaurant.","Verify use, occupancy, alteration scope, and relevant agency requirements.","Identify affected egress, accessibility, fire protection, and systems reviews.","Document the code basis and update it if the project changes."],"question":"Should you automatically use the newest published model code?","answer":"No. Verify the adopted edition and local amendments, unless the exam gives a specific basis.","trap":"Model publication and local adoption are different events.","refs":["R36"],"visual":null,"table":null},{"id":"5.1-2","title":"Turn requirements into a register","preview":"A rule is useful when someone can prove compliance.","explain":["A requirements register links each applicable requirement to an owner, document, and verification method.","Track unresolved interpretations and obtain appropriate clarification. Keep the resolution with the project record."],"steps":["Example: the project needs a compliant accessible entrance route.","Assign design and review responsibilities for grading, thresholds, doors, and clearances.","Identify the drawings or calculations that demonstrate the result.","Recheck the connected route after changes to grading or floor elevations."],"question":"Why is checking only the entrance door insufficient?","answer":"The whole required route and its connected elements must work together.","trap":"Separate compliant details can still form a noncompliant overall system.","refs":["R37","R38"],"visual":null,"table":{"headers":["Requirement","Document / evidence","Owner","Verification"],"rows":[["Accessible route","Plan + grading + sections","Architecture / civil","Coordinated route review"],["Egress strategy","Code plan + calculations","Architect","Independent check"],["Fire-system design","Engineering documents","Assigned engineer","Discipline + AHJ review"]]}},{"id":"5.1-3","title":"Separate code approval from all legal duties","preview":"Different requirements can apply at the same time.","explain":["Local code enforcement and federal accessibility obligations are not identical processes. A local approval does not automatically eliminate other applicable obligations.","When requirements overlap, identify each applicable rule and resolve the design through the proper review process."],"steps":["Example: an owner says a permit proves every accessibility issue is resolved.","Review the applicable standards and project scope.","Identify any remaining gap and develop a compliant response.","Record the analysis and coordinate necessary revisions."],"question":"Can an owner waive an applicable accessibility requirement to save money?","answer":"Owner preference does not remove a legal requirement. Address the issue through the applicable rules.","trap":"Do not confuse owner acceptance with lawful compliance.","refs":["R37","R38","R39"],"visual":null,"table":null},{"id":"5.1-4","title":"Keep professional responsibility assigned","preview":"Coordinate the review without practicing outside your role.","explain":["Allocate each technical review to an appropriately qualified professional. Verify the project’s licensure, signing, and submission requirements.","Communicate risks and unresolved issues through the team’s process. Document decisions and maintain a reliable record."],"steps":["Example: a late structural change affects an exit passage.","The structural professional addresses the structure. The architect evaluates the architectural and egress effects.","Coordinate the revised documents before issue.","Escalate a conflict that cannot be resolved within the available authority."],"question":"Does assigning the engineer remove the need to coordinate the changed space?","answer":"No. Discipline responsibility and project integration are both required.","trap":"Coordination does not give permission to sign another discipline’s work without appropriate responsibility.","refs":["R12","R36","R50"],"visual":null,"table":null}],"5.2":[{"id":"5.2-1","title":"Separate QA from QC","preview":"Build the process, then check the actual work.","explain":["Quality assurance (QA) establishes the conditions for reliable work: procedures, qualified staff, standards, and review gates.","Quality control (QC) checks particular deliverables against requirements. Both need time, people, and follow-through."],"steps":["QA example: the firm requires an independent drawing review before issue.","QC example: the reviewer finds an inconsistent door rating.","Correction: the responsible author fixes all affected documents.","Verification: the reviewer confirms the corrected rating and closes the item."],"question":"Is writing a checklist enough to establish that the issued drawings were checked?","answer":"No. The team must use it and record the review and resolution.","trap":"A process that exists only on paper does not verify the work.","refs":["R32","R33"],"visual":"quality","table":null},{"id":"5.2-2","title":"Budget review and correction time","preview":"Checking is planned work, not leftover time.","explain":["Choose the review level based on complexity, risk, phase, and scope. Identify the reviewer, required inputs, and acceptance criteria.","Allow time to fix findings and recheck them. Independent review is less useful if no time remains for correction."],"steps":["Example: issue date is Friday.","Plan a coordinated review on Tuesday, corrections Wednesday, and verification Thursday.","If a key consultant file arrives Thursday, the planned review sequence fails.","Resolve the input date or issue plan. Do not quietly delete verification."],"question":"What is missing from a schedule that includes a reviewer but no correction allowance?","answer":"A realistic path from findings to a verified issue.","trap":"The deadline does not lower the required standard of professional care.","refs":["R33","R34"],"visual":null,"table":null},{"id":"5.2-3","title":"Prioritize risks with an action owner","preview":"A risk score helps prioritize; it does not solve the risk.","explain":["A risk is an uncertain event with a possible impact. A live issue has already occurred. Record the distinction.","A simple probability × impact score can rank attention. The scales are project-defined and ordinal; the product is not a probability of loss."],"steps":["Example scoring assumption: probability and impact each use 1 to 3.","Late owner equipment data scores 3 × 2 = 6. Rare severe water intrusion scores 1 × 3 = 3.","Use these scores to organize discussion, but still address severe consequences.","Assign an owner, action, trigger, and review date to each risk."],"question":"Does a lower score mean a severe life-safety issue may be ignored?","answer":"No. Mandatory requirements and severity can override a simple ranking.","trap":"Do not treat an arbitrary score as a precise financial prediction.","refs":["R35","R26"],"visual":null,"table":{"headers":["Risk","Response","Owner","Trigger"],"rows":[["Late equipment data","Set interim data deadline","PM","Data missing on agreed date"],["Unresolved envelope interface","Specialist review","Project architect","Detail gate not passed"],["Uncertain existing structure","Obtain investigation","Assigned lead","Design depends on unknown capacity"]]}},{"id":"5.2-4","title":"Reduce risk without promising perfection","preview":"Reasonable professional care still requires active checking.","explain":["A professional standard of care is not a guarantee that no error can occur. Avoid casually accepting absolute performance promises.","Risk management also includes clear scope, capable staffing, coordinated agreements, timely communication, and documented review."],"steps":["Example: the owner asks for a promise of “zero change orders.”","Identify why changes can occur: owner choices, conditions, or design issues.","Evaluate the proposed promise through the firm’s contract review process.","Continue appropriate design review. Avoid substituting a disclaimer for actual care."],"question":"Does the standard of care excuse skipping a planned review?","answer":"No. It describes professional performance, not permission to ignore known risks.","trap":"“No guarantee of perfection” is not “no responsibility.”","refs":["R34","R35"],"visual":null,"table":null}],"5.3":[{"id":"5.3-1","title":"Check the interfaces, not just each sheet","preview":"A clean individual drawing can still conflict with another.","explain":["Coordinate dimensions, levels, loads, openings, devices, and access across disciplines. Use the current revisions.","Check physical space and the information used to build it. A model clash report covers only some coordination problems."],"steps":["Example: a duct passes through a structural beam above a ceiling.","Identify the current duct size, insulation, beam depth, and ceiling height.","Assign feasible changes to the appropriate designers.","Check that the solution also preserves maintenance access and other nearby systems."],"question":"Is moving the duct enough if it blocks a required service-access panel?","answer":"No. Recheck the surrounding interfaces after the move.","trap":"Removing one clash can create another. Verify the whole affected area.","refs":["R33","R28"],"visual":"clash","table":null},{"id":"5.3-2","title":"Coordinate drawings with specifications","preview":"The requirements must agree wherever they appear.","explain":["Compare plans, details, schedules, specifications, and consultant documents. Different media can prescribe conflicting requirements.","When conflicts appear, resolve them through the responsible authors. Do not rely on an invented universal order of precedence."],"steps":["Example: a door schedule shows one fire rating and the detail shows another.","Confirm the governing design requirement.","Correct the schedule, detail, and related hardware or specification references.","Recheck other occurrences of that door type."],"question":"Should you automatically choose the more expensive requirement?","answer":"No. Determine the correct requirement and follow the contract’s interpretation process.","trap":"Copying a typical detail without checking its applicability can multiply errors.","refs":["R33","S06"],"visual":null,"table":{"headers":["Item","Cross-check"],"rows":[["Door type","Plan tag ↔ schedule ↔ detail ↔ hardware"],["Wall system","Plan ↔ section ↔ fire assembly ↔ specification"],["Equipment","Schedule ↔ loads ↔ connections ↔ access"],["Finish","Room schedule ↔ elevations ↔ specification"]]}},{"id":"5.3-3","title":"Review constructability and access","preview":"Ask whether the design can be assembled and maintained.","explain":["Constructability review considers interfaces, installation space, tolerances, sequencing implications, and practical access.","It does not transfer the contractor’s means-and-methods responsibility. Design requirements and construction execution remain related but distinct."],"steps":["Example: a large replacement unit is shown in a small mechanical room.","Check the route for delivery, replacement, and maintenance.","Review door openings, turning space, lifting constraints, and removable elements.","Coordinate a feasible design without casually directing the contractor’s installation method."],"question":"Is sufficient operating clearance enough if the unit cannot be removed for replacement?","answer":"No. Review the required service and replacement access too.","trap":"A model that fits geometrically may still be impractical to assemble.","refs":["R33","R15"],"visual":null,"table":null},{"id":"5.3-4","title":"Close a review finding with proof","preview":"“Fixed” is a claim. Verification is evidence.","explain":["Use an issue log with location, requirement, responsible author, due date, and status. Keep the original finding visible.","Verify the correction and related effects before closing. Reopen an item if later revisions invalidate the fix."],"steps":["Example: QC-14 identifies conflicting ceiling heights.","The architect revises the plan and section. MEP confirms its equipment still fits.","The checker reviews the new files and records the revisions.","Only then change QC-14 from “corrected” to “verified / closed.”"],"question":"What is missing from an email saying only “done”?","answer":"The changed location, revision, verification, and confirmation of related impacts.","trap":"A completed action is not always a resolved issue.","refs":["R33"],"visual":"quality","table":{"headers":["Status","Evidence"],"rows":[["Open","Finding and required result"],["Assigned","Responsible person + due date"],["Corrected","Revised document locations"],["Verified","Checker confirms coordinated result"],["Closed","Record retained; no open related action"]]}}],"5.4":[{"id":"5.4-1","title":"Turn design goals into measurable criteria","preview":"“Good daylight” needs a definition before it can be verified.","explain":["Record the owner’s goals as requirements with a metric, target, method, and decision-maker. Distinguish mandatory requirements from preferences.","Agree how each objective will be checked. A target without a verification method is difficult to manage."],"steps":["Example project assumption: a meeting room must hold 20 people in the approved furniture layout.","Record occupancy, circulation, accessibility, sightlines, and equipment constraints.","Review layouts against these criteria at each phase.","Do not assume matching floor area proves the room performs as intended."],"question":"What makes an objective testable?","answer":"A defined outcome, a target or acceptance criterion, and a stated way to verify it.","trap":"An attractive image is not evidence that all functional goals are met.","refs":["R31","S16"],"visual":null,"table":{"headers":["Goal","Measurable project criterion","Evidence"],"rows":[["Capacity","20 people in agreed layout","Furniture + circulation review"],["Maintenance","Required service access retained","Access-zone review"],["Energy","Agreed modeled target","Documented analysis"],["Budget","Approved construction allocation","Coordinated estimate"]]}},{"id":"5.4-2","title":"Trace goals into the documents","preview":"Link the brief to drawings, specifications, and checks.","explain":["A traceability matrix shows where each requirement is addressed and how it is verified. Use it through design and change reviews.","Code compliance is one layer. The project may also have agreed functional, cost, durability, acoustic, or environmental criteria."],"steps":["Example: the owner requires easy maintenance in a public lobby.","Translate the goal into material performance, access, and cleaning requirements.","Locate those requirements in the finishes, details, and specifications.","Review substitutions against the same criteria."],"question":"If a substitute meets code, must it meet every owner design objective?","answer":"Not necessarily. Check the additional agreed requirements separately.","trap":"Minimum legal compliance does not prove equivalence to the project brief.","refs":["R31","R33"],"visual":null,"table":{"headers":["Requirement","Design response","Document","Check"],"rows":[["Maintainable lobby","Durable finish + accessible edges","Finish schedule + detail","Material and access review"],["Acoustic privacy","Appropriate enclosure and seals","Wall / door / ceiling documents","Coordinated performance review"],["Future replacement","Removal route retained","Plan + section","Access study"]]}},{"id":"5.4-3","title":"Evaluate substitutions as decisions","preview":"A cheaper item can weaken an important objective.","explain":["Compare the proposed substitution with the required performance and its effects on interfaces, cost, time, and warranties.","Identify which differences require an owner decision, design revision, or contract modification. Record the basis of acceptance or rejection."],"steps":["Example: alternate glazing saves $40,000 but changes solar performance and exterior appearance.","Ask the responsible designers to assess energy and system impacts.","Check whether added cooling capacity would reduce the saving.","Present the coordinated comparison for an authorized decision."],"question":"Does equal purchase price prove equal value?","answer":"No. Compare performance, lifecycle effects, installation, interfaces, and schedule.","trap":"Approval should identify the accepted differences, not simply say “similar.”","refs":["R33","S16"],"visual":null,"table":{"headers":["Check","Why it matters"],"rows":[["Required performance","Preserves the agreed objective"],["Interfaces","Avoids new design conflicts"],["Full cost","Includes resulting changes"],["Schedule","Considers availability and review"],["Approval","Confirms decision authority"]]}},{"id":"5.4-4","title":"Verify the objective survived the changes","preview":"Return to the brief before every major issue.","explain":["Use phase reviews to compare the developing project with agreed objectives. Track the effect of every material change.","Commissioning and closeout can provide evidence for specified systems and outcomes. The exact scope and responsibility must be assigned."],"steps":["Example: several revisions reduce a storage room’s usable capacity.","At the next gate, compare the current layout with the original capacity criterion.","Identify the gap and propose a compliant or properly authorized revision.","Update the brief only after the correct decision, not merely because the drawings changed."],"question":"If the final drawings are internally consistent, is the design automatically successful?","answer":"No. They may consistently describe a project that no longer meets the agreed requirements.","trap":"Do not quietly redefine success to match the current design.","refs":["R31","R33","S16"],"visual":null,"table":null}]};
